# frozen_string_literal: true

require 'yaml'

module Ceradoc
  module Roundtrip
    class Vector
      # A bistable ratchet list, the KnownFailures pattern applied to a
      # vector-side machinery gap (loader or producer).
      #
      # Entries are generated by the sealer and are part of the sealed
      # fixture set. The vector spec fails on a gap that is failing but
      # NOT listed (a new gap must be sealed knowingly) and on a gap
      # that is listed but now passes (fixing the machinery must
      # shrink the list). Never add an entry to make CI green.
      class Gaps
        def initialize(entries) = @entries = entries

        def self.load(file)
          new(YAML.safe_load_file(file) || {})
        rescue Errno::ENOENT
          new({})
        end

        def include?(gap_id) = @entries.key?(gap_id)

        def reason(gap_id) = @entries[gap_id]

        def ids = @entries.keys

        def size = @entries.size

        # @param do_fail [Hash{String=>String}] gap ids failing now => detail
        # @return [Array<String>] ids whose listing no longer matches
        #   reality: listed but passing, or failing but unlisted
        def drift(do_fail)
          (@entries.keys - do_fail.keys) + (do_fail.keys - @entries.keys)
        end

        def self.write(entries, file)
          File.write(file, + "#{header}#{YAML.dump(entries.sort.to_h)}")
          entries.size
        end

        HEADER = <<~TEXT
          # Generated by `rake roundtrip:vectors:seal` — do not edit by hand.
          # Listed id => first failure detail. The vector spec fails when a
          # listed gap starts passing or an unlisted one starts failing, so
          # this list can only shrink. Never add an entry to make CI green.
        TEXT
        private_constant :HEADER

        def self.header = HEADER
      end
    end
  end
end
